/* pf_win32_crt_shim_types.h -- HAND-WRITTEN project data (carrier/gen
 * policy, NOT generated by gen_bindings.py; do not run a generator over
 * this file). Referenced by carrier/gen/gen_bindings.py's own
 * GUEST_CRT_PRE_INCLUDES list (a quoted, not angle-bracket, entry) and
 * therefore #include'd near the top of the CRT-imports block in
 * carrier/gen/pf_bindings_src.h, itself force-included (/FI) ahead of
 * every src/icytower/*.c translation unit compiled into the carrier.
 *
 * Purpose (PROMOTIONS.md batch 12, "Four generator gaps", gap 1):
 * src/icytower/play.c reaches KERNEL32.QueryPerformanceCounter/Frequency
 * through the import table and needs the real Win32 SDK's `LARGE_INTEGER`
 * type to call them. Nothing in the generated headers (which carry only
 * the game and Allegro scopes) supplies it, so play.c carries its own
 * fallback:
 *
 *   #ifndef _WINDOWS_
 *   typedef union it_large_integer {
 *       struct { unsigned int LowPart; int HighPart; } u;
 *       double _align;
 *   } LARGE_INTEGER;
 *   int __stdcall QueryPerformanceCounter(LARGE_INTEGER *lpPerformanceCount);
 *   int __stdcall QueryPerformanceFrequency(LARGE_INTEGER *lpFrequency);
 *   #endif
 *
 * That fallback is correct for the standalone worlds (nothing else defines
 * _WINDOWS_ there, so it becomes live, and PROMOTIONS.md batch 12 already
 * verified 0 errors both standalone compiles with it live). In the
 * CARRIER world, though, gen_bindings.py's GUEST_CRT_IMPORTS mechanism
 * binds `QueryPerformanceCounter`/`QueryPerformanceFrequency` to real
 * object-like macros (`#define QueryPerformanceCounter (*(PFN_crt_...*)
 * 0x...)`) that call through the GUEST's own IAT slot -- the same
 * divergence-008 reasoning already applied to `rand`, now needed here too
 * because carrier/src/det.cpp's own `det_wrap_QueryPerformanceCounter`
 * only intercepts the GUEST's slot, and a src/ call reaching the
 * carrier's own linked-in QueryPerformanceCounter instead would read the
 * real host clock even under --det. Those macros make play.c's OWN
 * fallback declarations of the two functions a syntax error the moment
 * this header's macro rewrites the identifier mid-declaration (`int
 * __stdcall (*(PFN_crt_QueryPerformanceCounter *)0x...)(...)`) -- so the
 * fallback block must never fire in the carrier world at all.
 *
 * This header supplies exactly the type play.c's own fallback would have
 * (byte-identical spelling, including the named `u` member -- valid
 * against real <windows.h> too, per that header's own comment) and claims
 * the same `_WINDOWS_` guard name, so that by the time play.c's own
 * `#ifndef _WINDOWS_` is reached, the guard is already taken and its
 * entire fallback block (LARGE_INTEGER typedef AND both prototypes) is
 * skipped -- without pulling in a real <windows.h> (which would also
 * bring in BOOL/WORD/DWORD/... typedefs that could collide with
 * DWARF-recovered names in it_types.h; deliberately avoided).
 */
#ifndef _WINDOWS_
#define _WINDOWS_ 1

typedef union it_large_integer {
    struct { unsigned int LowPart; int HighPart; } u;
    double _align;
} LARGE_INTEGER;

#endif /* _WINDOWS_ */
